import * as THREE from 'three';

export function museumObjectIsVisible(camera, bounds, retained = true) {
  camera.updateMatrixWorld();
  const projection = new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
  const frustum = new THREE.Frustum().setFromProjectionMatrix(projection);
  // A small exit margin keeps the panel calm at the screen edge. Returning
  // requires the actual object to re-enter the frame.
  return frustum.intersectsBox(bounds.clone().expandByScalar(retained ? .18 : 0));
}

export function museumBookOpening({ hovered, active, travelling, distance }) {
  if (active && !travelling && distance <= 1.8) return 1;
  return hovered ? .38 : 0;
}

export function museumAttentionStation(camera, stations, previous = '') {
  const direction = camera.getWorldDirection(new THREE.Vector3());
  let chosen = null, score = Infinity;
  for (const station of stations) {
    if(station.autoActivate===false)continue;
    const centre = station.bounds.getCenter(new THREE.Vector3());
    const toObject = centre.sub(camera.position).normalize();
    const distance = Math.hypot(camera.position.x-station.eye[0],camera.position.z-station.eye[2]);
    const retained = station.id === previous;
    if (distance > (retained ? 3.2 : 2.4) || direction.dot(toObject) < (retained ? -.05 : .72)) continue;
    if (!museumObjectIsVisible(camera, station.bounds, retained)) continue;
    const rank = distance + (1-direction.dot(toObject)) * 2 - (retained ? .8 : 0);
    if (rank < score) { chosen = station.id; score = rank; }
  }
  return chosen;
}

export function museumConstrainedLook(camera, proposed, { overview = false, reference, bounds = [] } = {}) {
  const current = new THREE.Euler().setFromQuaternion(camera.quaternion, 'YXZ');
  if (overview && reference) {
    const delta = Math.atan2(Math.sin(proposed.yaw-reference.yaw),Math.cos(proposed.yaw-reference.yaw));
    return { yaw:reference.yaw+THREE.MathUtils.clamp(delta,-.045,.045),pitch:THREE.MathUtils.clamp(proposed.pitch,reference.pitch-.03,reference.pitch+.03) };
  }
  const next={yaw:proposed.yaw,pitch:THREE.MathUtils.clamp(proposed.pitch,-.4,.28)};
  const probe=camera.clone();
  probe.clearViewOffset();probe.fov=Math.min(70,probe.fov)*.72;probe.updateProjectionMatrix();
  function containsArchitecture(pose){
    probe.rotation.set(pose.pitch,pose.yaw,0,'YXZ');
    return bounds.some(box=>museumObjectIsVisible(probe,box,false));
  }
  if(!bounds.length||containsArchitecture(next))return next;
  const origin={yaw:current.y,pitch:current.x};
  const turn=Math.atan2(Math.sin(next.yaw-current.y),Math.cos(next.yaw-current.y));
  let low=0,high=1;
  for(let i=0;i<9;i++){
    const t=(low+high)/2,pose={yaw:origin.yaw+turn*t,pitch:THREE.MathUtils.lerp(origin.pitch,next.pitch,t)};
    if(containsArchitecture(pose))low=t;else high=t;
  }
  return {yaw:origin.yaw+turn*low,pitch:THREE.MathUtils.lerp(origin.pitch,next.pitch,low)};
}
